 CREATE OR REPLACE FUNCTION public.get_ssissa_payment(v_client_id integer, pagenumber bigint, pagesize bigint)                                                                                                                                                                                                                       
  RETURNS TABLE(totalcount bigint, transaction_id bigint, account_no_tx character varying, client_account_id bigint, transaction_dt date, transaction_source_cd character varying, transaction_source character varying, benefit_start_dt date, benefit_end_dt date, transaction_amount_no numeric, reference_transaction_id integer)
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                   
 AS $function$                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                   
 DECLARE                                                                                                                                                                                                                                                                                                                           
         v_pageoffset int;                                                                                                                                                                                                                                                                                                         
     v_pagenumber int;                                                                                                                                                                                                                                                                                                             
 BEGIN                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                   
         v_pagenumber := pagenumber-1;                                                                                                                                                                                                                                                                                             
     v_pageoffset = v_pagenumber * pagesize;                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                                                   
         return query                                                                                                                                                                                                                                                                                                              
 select count(1) over(),tat.transaction_id ,tca.account_no_tx,tca.client_account_id,tat.transaction_dt,tat.transaction_source_cd,                                                                                                                                                                                                  
 (select value_tx from tb_picklist_values where PICKLIST_type_id=38 AND delete_sw='N' AND active_sw='Y'                                                                                                                                                                                                                            
 AND TRIM(PICKLIST_VALUE_CD)=TRIM(tat.transaction_source_cd)) AS transaction_source,tat.benefit_start_dt,tat.benefit_end_dt,                                                                                                                                                                                                       
 tat.transaction_amount_no,tat.reference_transaction_id                                                                                                                                                                                                                                                                            
 from tb_client_account tca                                                                                                                                                                                                                                                                                                        
 join tb_account_transaction tat on tat.client_account_id =tca.client_account_id and tat.delete_sw ='N'                                                                                                                                                                                                                            
 where tca.client_id =v_client_id and tca.status_cd = '592' and tat.transaction_source_cd in ('586','587')                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                   
 LIMIT pagesize OFFSET v_pageoffset;                                                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                                                                                   
 END;                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                   
 $function$                                                                                                                                                                                                                                                                                                                          

